MOD = 1000000007

def numoffbt(arr, n):
    arr.sort()
    count = {}
    for x in arr:
        count[x] = 1

    for i in range(n):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                right = arr[i] // arr[j]
                if right in count:
                    count[arr[i]] = (count[arr[i]] + count[arr[j]] * count.get(right, 0)) % MOD

    total = sum(count.values()) % MOD
    return total

